    /** @var array<int, array{name: string, description: string}> */
    private const BAND_5 = [
        ['name' => 'Тропа Последнего Подъёма', 'description' => 'Участок перевала, за которым тропа идёт только вверх — отсюда виден весь путь, пройденный снизу, целиком.'],
        ['name' => 'Выступ Над Пропастью Ветра', 'description' => 'Скальный выступ на самом краю перевала — ветер здесь не утихает никогда, будто дует откуда-то значительно выше самих гор.'],
        ['name' => 'Площадка Птичьего Гнездовья', 'description' => 'Плоский уступ, усеянный остатками крупных гнёзд — размер некоторых из них заставляет усомниться, что их строили обычные птицы.'],
        ['name' => 'Тропа Высокого Эха', 'description' => 'Узкая тропа вдоль обрыва, на которой любой крик разносится неправдоподобно далеко — будто здесь воздуху нечем его остановить.'],
