        ['name' => 'Вершина Грани Небес', 'description' => 'Высшая точка Гранитного Перевала — здесь тропа наконец заканчивается, а дальше, насколько видит глаз, нет уже ничего, кроме неба и памяти о Раскалывании.'],
    ];

    public function run(): void
    {
        $bands = [
            ['range' => [1280, 1329], 'pool' => self::BAND_1],
            ['range' => [1330, 1379], 'pool' => self::BAND_2],
            ['range' => [1380, 1429], 'pool' => self::BAND_3],
            ['range' => [1430, 1479], 'pool' => self::BAND_4],
            ['range' => [1480, 1529], 'pool' => self::BAND_5],
        ];

        $updated = 0;

        foreach ($bands as $band) {
            [$fromId, $toId] = $band['range'];
            $pool = $band['pool'];
            $poolSize = count($pool);

            $locationIds = DB::table('locations')
                ->whereBetween('id', [$fromId, $toId])
                ->orderBy('id')
                ->pluck('id')
                ->values();

            foreach ($locationIds as $index => $locationId) {
                $entry = $pool[$index % $poolSize];

                DB::table('locations')->where('id', $locationId)->update([
                    'name' => $entry['name'],
                    'description' => $entry['description'],
                    'updated_at' => now(),
                ]);
                $updated++;
            }

            $this->command?->info(sprintf(
                'полоса %d-%d: %d локаций переименовано (пул из %d названий)',
                $fromId, $toId, $locationIds->count(), $poolSize,
            ));
        }

        $this->command?->info("GranitePassLocationFlavorSeeder: обновлено локаций — {$updated}");
    }
}
